// Android adaptive launcher icon as a vector drawable (the "two of us" logo), written on every
// `expo prebuild`, since android/ is generated. Source of truth: assets/logo.svg (100x100) and
// assets/logo-dark.svg; the colours below must match them. Legacy (API < 26) PNG mipmaps are still
// generated by Expo from assets/icon.png.
const fs = require("fs");
const path = require("path");
const { withDangerousMod } = require("expo/config-plugins");

const LIGHT = {
  bg: "#FFF4D6",
  left: "#C2185B",
  right: "#F48FB1",
  overlap: "#7A0E3A",
  sparkle: "#C2185B",
};
const DARK = {
  bg: "#7A0E3A",
  left: "#F48FB1",
  right: "#FFF4D6",
  overlap: "#FFFFFF",
  sparkle: "#F48FB1",
};

// Logo geometry (logo.svg units). Seen from (55, 40), the furthest painted points (the left
// circle's edge and the sparkle's tips) are 42 units away; scale so they sit on the 33dp radius of
// the adaptive-icon safe zone, centred in the 108dp canvas.
const S = 33 / 42;
const TX = 54 - 55 * S;
const TY = 54 - 40 * S;
const circle = (cx) => `M${cx - 22},52a22,22 0 1,0 44,0a22,22 0 1,0 -44,0`;
const SPARKLE = "M80,14 Q80,22 88,22 Q80,22 80,30 Q80,22 72,22 Q80,22 80,14 Z";

const foreground = (c) => `<?xml version="1.0" encoding="utf-8"?>
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="108dp"
    android:height="108dp"
    android:viewportWidth="108"
    android:viewportHeight="108">
    <group
        android:scaleX="${S.toFixed(4)}"
        android:scaleY="${S.toFixed(4)}"
        android:translateX="${TX.toFixed(3)}"
        android:translateY="${TY.toFixed(3)}">
        <path android:fillColor="${c.left}" android:pathData="${circle(39)}" />
        <path android:fillColor="${c.right}" android:pathData="${circle(61)}" />
        <group>
            <clip-path android:pathData="${circle(39)}" />
            <path android:fillColor="${c.overlap}" android:pathData="${circle(61)}" />
        </group>
        <path android:fillColor="${c.sparkle}" android:pathData="${SPARKLE}" />
    </group>
</vector>
`;

const colors = (c) => `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="bb_icon_background">${c.bg}</color>
</resources>
`;

const ADAPTIVE = `<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@color/bb_icon_background" />
    <foreground android:drawable="@drawable/bb_icon_foreground" />
</adaptive-icon>
`;

const write = (file, text) => {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, text);
};

module.exports = function withVectorAdaptiveIcon(config) {
  return withDangerousMod(config, [
    "android",
    async (cfg) => {
      const res = path.join(cfg.modRequest.platformProjectRoot, "app/src/main/res");
      write(path.join(res, "drawable/bb_icon_foreground.xml"), foreground(LIGHT));
      write(path.join(res, "drawable-night/bb_icon_foreground.xml"), foreground(DARK));
      write(path.join(res, "values/bb_icon.xml"), colors(LIGHT));
      write(path.join(res, "values-night/bb_icon.xml"), colors(DARK));
      // Same names as Expo's, so the manifest's @mipmap/ic_launcher picks these on API 26+ and the
      // generated PNG mipmaps on older devices.
      write(path.join(res, "mipmap-anydpi-v26/ic_launcher.xml"), ADAPTIVE);
      write(path.join(res, "mipmap-anydpi-v26/ic_launcher_round.xml"), ADAPTIVE);
      return cfg;
    },
  ]);
};
